  ["-canvas-rce", "canvas-rce"],"},{"rank":3,"score":42.3433,"file_path":"packages/utils/src/example-targets.ts","start_line":51,"end_line":68,"focus_line":53,"snippet_start_line":53,"snippet_end_line":68,"symbol_start_line":53,"symbol_end_line":68,"language":"TypeScript","kind":"function","symbol_id":"gh/thedannywahl/pantoken:TypeScript:packages/utils/src/example-targets.ts:function:audienceFlags","symbol_name":"audienceFlags","qualified_name":"audienceFlags","signature":"function audienceFlags(example: string): Set<ExampleAudience>","signals":["path","body","symbol-name","signature","symbol-usage","complete-symbol"],"snippet":"function audienceFlags(example: string): Set<ExampleAudience> {
  const fenceStart = example.indexOf("```");
  const metadata = fenceStart < 0 ? example : example.slice(0, fenceStart);
  const fenceInfo =
    fenceStart < 0 ? "" : (example.slice(fenceStart + 3).split(/\r?\n/u, 1)[0] ?? "");
  const metadataTokens = metadata.trim().split(/\s+/u).filter(Boolean);
  const metadataIsFlags = metadataTokens.every((token) => /^-[a-z][a-z0-9-]*$/u.test(token));
  const flags = new Set<ExampleAudience>();

  for (const token of [...(metadataIsFlags ? metadataTokens : []), ...fenceInfo.split(/\s+/u)]) {
    const audience = AUDIENCE_FLAGS.get(token);
    if (audience) flags.add(audience);
  }

  return flags;
}"},{"rank":4,"score":35.6925,"file_path":"docs/.vitepress/i18n.json","start_line":21,"end_line":21,"focus_line":21,"snippet_start_line":21,"snippet_end_line":21,"symbol_start_line":21,"symbol_end_line":21,"language":"JSON","kind":"section","symbol_id":"gh/thedannywahl/pantoken:JSON:docs/.vitepress/i18n.json:section:sidebar.canvasRce","symbol_name":"canvasRce","qualified_name":"sidebar.canvasRce","signature":"json key sidebar.canvasRce","signals":["path","body","exact-symbol","symbol-name","constraint:entity"],"snippet":"  "sidebar.canvasRce": { "message": "Canvas RCE", "translate": "always" },"},{"rank":5,"score":33.2532,"file_path":"docs/scripts/canvas-rce-pwa.ts","start_line":26,"end_line":90,"focus_line":28,"snippet_start_line":28,"snippet_end_line":90,"symbol_start_line":28,"symbol_end_line":90,"language":"TypeScript","kind":"function","symbol_id":"gh/thedannywahl/pantoken:TypeScript:docs/scripts/canvas-rce-pwa.ts:function:configureCanvasRcePwa","symbol_name":"configureCanvasRcePwa","qualified_name":"configureCanvasRcePwa","signature":"function configureCanvasRcePwa( renderDir: string, logoPath: string, reversedLogoPath: string, ): void","signals":["path","body","symbol-name","constraint:entity","complete-symbol"],"snippet":"export function configureCanvasRcePwa(
  renderDir: string,
  logoPath: string,
  reversedLogoPath: string,
): void {
  const indexPath = join(renderDir, "index.html");
  let html = readFileSync(indexPath, "utf8");
  html = replaceRequired(
    html,
    '<meta name="application-name" content="Canvas Theme Editor" />',
    '<meta name="application-name" content="Pantoken" />',
  );
  html = replaceRequired(html, "<title>Canvas Theme Editor</title>", "<title>Pantoken</title>");
  html = replaceRequired(
    html,
    '<link rel="manifest" href="/manifest.webmanifest" />',
    `<link rel="manifest" href="/manifest.webmanifest" />
    <link rel="icon" href="/icon-192.png" sizes="192x192" type="image/png" media="(prefers-color-scheme: light)" data-pantoken-themed-icon />
    <link rel="icon" href="/icon-192-dark.png" sizes="192x192" type="image/png" media="(prefers-color-scheme: dark)" />
    <link rel="apple-touch-icon" href="/apple-touch-icon.png" sizes="180x180" media="(prefers-color-scheme: light)" />
    <link rel="apple-touch-icon" href="/apple-touch-icon-dark.png" sizes="180x180" media="(prefers-color-scheme: dark)" />`,
  );
  writeFileSync(indexPath, html);

  const publicDir = join(renderDir, "public");
  const manifestPath = join(publicDir, "manifest.webmanifest");
  const manifest = JSON.parse(readFileSync(manifestPath, "utf8")) as Record<string, unknown>;
  Object.assign(manifest, {
    id: APP_BASE,
    name: "Pantoken",
    short_name: "Pantoken",
    start_url: APP_BASE,
    scope: APP_BASE,
    background_color: BACKGROUND_COLOR,
    theme_color: THEME_COLOR,
    // Desktop Chrome doesn't apply manifest icon updates after installation. Keep these fixed and
    // let the document's opt-in favicon reflect live theme-color changes instead. Manifest icons
    // don't reliably support per-icon `media` queries across browsers, so this stays on the light
    // set — the `<link>` tags above (which OS-level "add to dock"/shortcut features actually read
    // live) are what pick the dark-contrasting variant.
    icons: ICON_SIZES.map((size) => ({
      src: `${APP_BASE}icon-${size}.png`,
      sizes: `${size}x${size}`,
      type: "image/png",
      purpose: "any maskable",
    })),
  });
  writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);

  const iconSvg = appIconSvg(readFileSync(logoPath, "utf8"), BACKGROUND_COLOR);
  for (const size of ICON_SIZES) {
    writePng(iconSvg, size, join(publicDir, `icon-${size}.png`));
  }
  writePng(iconSvg, 180, join(publicDir, "apple-touch-icon.png"));

  // Dark-dock-safe variant: the reversed (light) mark on the same dark navy used for theme-color,
  // so a dock/taskbar shortcut icon installed under a dark OS appearance doesn't render dark-on-dark.
  const iconSvgDark = appIconSvg(readFileSync(reversedLogoPath, "utf8"), THEME_COLOR);
  for (const size of ICON_SIZES) {
    writePng(iconSvgDark, size, join(publicDir, `icon-${size}-dark.png`));
  }
